-- Remove only the retired fifth skip from the fourteen live V2 core questions.
-- Keep canonical indexes 0..3, managed text, background answers, reports and price.
-- A single guarded update prevents partial changes; rerunning is safe.
UPDATE quiz_questions SET options_json=json_remove(options_json,'$[4]'),updated_at=CURRENT_TIMESTAMP WHERE test_id='attachment-style' AND active=1 AND id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14') AND json_extract(report_config_json,'$.version')='attachment-fixed-v2' AND json_extract(report_config_json,'$.kind')='core' AND json_array_length(options_json)=5 AND ((SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1 AND id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14') AND json_extract(report_config_json,'$.version')='attachment-fixed-v2' AND json_extract(report_config_json,'$.kind')='core')=14 AND (SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1 AND id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14') AND json_extract(report_config_json,'$.version')='attachment-fixed-v2' AND json_extract(report_config_json,'$.kind')='core' AND (json_array_length(options_json)=4 OR (json_array_length(options_json)=5 AND json_extract(options_json,'$[4].fixed.tag')='skip' AND json_extract(options_json,'$[4].optionId')=json_extract(options_json,'$[4].fixed.id'))) AND json_extract(options_json,'$[0].styleKey') IN ('anxious','avoidant','secure','fearful') AND COALESCE(json_extract(options_json,'$[0].fixed.tag'),'') NOT IN ('','skip') AND json_extract(options_json,'$[1].styleKey') IN ('anxious','avoidant','secure','fearful') AND COALESCE(json_extract(options_json,'$[1].fixed.tag'),'') NOT IN ('','skip') AND json_extract(options_json,'$[2].styleKey') IN ('anxious','avoidant','secure','fearful') AND COALESCE(json_extract(options_json,'$[2].fixed.tag'),'') NOT IN ('','skip') AND json_extract(options_json,'$[3].styleKey') IN ('anxious','avoidant','secure','fearful') AND COALESCE(json_extract(options_json,'$[3].fixed.tag'),'') NOT IN ('','skip'))=14);

INSERT OR IGNORE INTO quiz_catalog_migrations(id) SELECT 'attachment-core-four-options-2026-10-08' WHERE (SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1 AND id IN ('attachment-style-fixed-v2-q01','attachment-style-fixed-v2-q02','attachment-style-fixed-v2-q03','attachment-style-fixed-v2-q04','attachment-style-fixed-v2-q05','attachment-style-fixed-v2-q06','attachment-style-fixed-v2-q07','attachment-style-fixed-v2-q08','attachment-style-fixed-v2-q09','attachment-style-fixed-v2-q10','attachment-style-fixed-v2-q11','attachment-style-fixed-v2-q12','attachment-style-fixed-v2-q13','attachment-style-fixed-v2-q14') AND json_extract(report_config_json,'$.version')='attachment-fixed-v2' AND json_extract(report_config_json,'$.kind')='core' AND json_array_length(options_json)=4)=14;
